contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address who) public payable {
        require(who != address(this));
        require(c.balances(who) == 0);

        uint256 ethBefore = address(c).balance;
        uint256 balBefore = c.balances(who); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 ethAfter = address(c).balance;
        uint256 balAfter = c.balances(who); if (__ESBMC_reverted()) return;

        assert(!reverted && balAfter == balBefore && ethAfter == ethBefore);
    }

    receive() external payable {}
}

